export const ExponentialLoad = zod
  .object({
    id: zod.int().describe("Unique integer identifier for this component."),
    name: zod
      .string()
      .describe(
        "Name of the component. Components of the same type (e.g., `PowerLoad`) must have unique names, but components of different types (e.g., `PowerLoad` and `ACBus`) can have the same name.",
      ),
    available: zod
      .boolean()
      .describe(
        "Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`). Unavailable components are excluded during simulations.",
      ),
    bus: zod
      .int()
      .describe("ID of the bus that this component is connected to."),
    active_power: zod
      .number()
      .describe(
        "Active power coefficient, P0. Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .",
      ),
    reactive_power: zod
      .number()
      .describe(
        "Reactive power coefficient, Q0. Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .",
      ),
    alpha: zod
      .number()
      .describe(
        "Exponent relating voltage dependency for active power. 0 = constant power only, 1 = constant current only, and 2 = constant impedance only.",
      ),
    beta: zod
      .number()
      .describe(
        "Exponent relating voltage dependency for reactive power. 0 = constant power only, 1 = constant current only, and 2 = constant impedance only.",
      ),
    base_power: zod
      .number()
      .describe("Base power of the unit for per unitization. Units: MVA."),
    power_units: zod
      .enum(["COMPONENT_BASE", "NATURAL_UNITS"])
      .describe(
        "Unit basis a stored value is expressed in. COMPONENT_BASE: per-unit against a base the component records itself. NATURAL_UNITS: the quantity's own physical unit. No system-wide option: a value per-unitized against a shared base records that base on the component and rides as COMPONENT_BASE. Used in three scopes, each read against its own record rather than a document-wide table: a component's own `power_units` (against that component's `base_power`), a cost payload's own `power_units` (e.g. `CostCurve`, against the owning component's `base_power`), and a time series association's own `unit_system` (governing only that one series).",
      ),
    max_active_power: zod
      .number()
      .describe(
        "Maximum active power that this load can demand. Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .",
      ),
    max_reactive_power: zod
      .number()
      .describe(
        "Maximum reactive power that this load can demand. Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .",
      ),
    conformity: zod
      .enum(["NON_CONFORMING", "CONFORMING", "UNDEFINED"])
      .optional()
      .default("UNDEFINED")
      .describe(
        "WECC classification of how a load tracks voltage and frequency variation, used in dynamic studies to decide how it is modeled during a disturbance. `CONFORMING` responds predictably and follows standard load modeling practice; `NON_CONFORMING` does not, as with a constant power load or one behind a complex control system; `UNDEFINED` leaves the classification unstated.",
      ),
    dynamic_injector: zod
      .int()
      .nullish()
      .describe("ID of the corresponding dynamic injection device, if any."),
  })
  .describe(
    "A voltage-dependent ZIP load, most commonly used for dynamics modeling.\n\nAn `ExponentialLoad` models active power as P = P0 * V^α and reactive power as Q = Q0 * V^β, where the exponents α and β select govern the voltage dependency. For an alternative three-part formulation of the ZIP model, see `StandardLoad`. For a simpler load model with no voltage dependency, see `PowerLoad`.",
  );

export type ExponentialLoad = zod.input<typeof ExponentialLoad>;
export type ExponentialLoadOutput = zod.output<typeof ExponentialLoad>;

