export const ThreeWindingTransformer = zod
  .object({
    id: zod.int().describe("Unique integer identifier for this component."),
    name: zod
      .string()
      .describe(
        "Name of the component. Components of the same type (e.g., `PowerLoad`) must have unique names, but components of different types (e.g., `PowerLoad` and `ACBus`) can have the same name.",
      ),
    primary_circuit: zod
      .int()
      .describe(
        "The primary `TransformerCircuit` connecting the primary bus to the star bus.",
      ),
    secondary_circuit: zod
      .int()
      .describe(
        "The secondary `TransformerCircuit` connecting the secondary bus to the star bus.",
      ),
    tertiary_circuit: zod
      .int()
      .describe(
        "The tertiary `TransformerCircuit` connecting the tertiary bus to the star bus.",
      ),
    star_bus: zod
      .int()
      .describe(
        "Star (hidden) Bus that this component (equivalent model) is connected to.",
      ),
    parameter_units: zod
      .enum(["NATURAL_UNITS", "COMPONENT_BASE"])
      .optional()
      .default("COMPONENT_BASE")
      .describe(
        "Unit basis a branch/injection impedance is stored in. NATURAL_UNITS: physical ohms (PSS/E RAW native for DC-line impedances). COMPONENT_BASE: per-unit on the component's own base (base_power MVA and voltage base); components whose per-unit data was historically on the system base record that system base in base_power, so there is no separate system-base option. PSS/E supplies device base for DC-line converters and CZ=2 transformer windings. A branch's shunt admittance halves (b, g) share the branch's one basis: NATURAL_UNITS stores them in siemens.",
      ),
    r_12: zod
      .number()
      .optional()
      .describe(
        "Measured resistance, referenced to the primary winding's base voltage, from primary to secondary windings (R1-2 in PSS/E). Units: per parameter_units — NATURAL_UNITS: ohm, COMPONENT_BASE: pu .",
      ),
    x_12: zod
      .number()
      .optional()
      .describe(
        "Measured reactance, referenced to the primary winding's base voltage, from primary to secondary windings (X1-2 in PSS/E). Units: per parameter_units — NATURAL_UNITS: ohm, COMPONENT_BASE: pu .",
      ),
    r_23: zod
      .number()
      .optional()
      .describe(
        "Measured resistance, referenced to the secondary winding's base voltage, from secondary to tertiary windings (R2-3 in PSS/E). Units: per parameter_units — NATURAL_UNITS: ohm, COMPONENT_BASE: pu .",
      ),
    x_23: zod
      .number()
      .optional()
      .describe(
        "Measured reactance, referenced to the secondary winding's base voltage, from secondary to tertiary windings (X2-3 in PSS/E). Units: per parameter_units — NATURAL_UNITS: ohm, COMPONENT_BASE: pu .",
      ),
    r_31: zod
      .number()
      .optional()
      .describe(
        "Measured resistance, referenced to the tertiary winding's base voltage, from tertiary to primary windings (R3-1 in PSS/E). Units: per parameter_units — NATURAL_UNITS: ohm, COMPONENT_BASE: pu .",
      ),
    x_31: zod
      .number()
      .optional()
      .describe(
        "Measured reactance, referenced to the tertiary winding's base voltage, from tertiary to primary windings (X3-1 in PSS/E). Units: per parameter_units — NATURAL_UNITS: ohm, COMPONENT_BASE: pu .",
      ),
    base_power_12: zod
      .number()
      .optional()
      .describe(
        "Base power for per unitization for primary-secondary windings. Units: MVA.",
      ),
    base_power_23: zod
      .number()
      .optional()
      .describe(
        "Base power for per unitization for secondary-tertiary windings. Units: MVA.",
      ),
    base_power_31: zod
      .number()
      .optional()
      .describe(
        "Base power for per unitization for tertiary-primary windings. Units: MVA.",
      ),
    admittance_units: zod
      .enum(["NATURAL_UNITS", "COMPONENT_MVAR", "COMPONENT_BASE"])
      .optional()
      .default("COMPONENT_BASE")
      .describe(
        "Unit basis a shunt admittance is stored in. NATURAL_UNITS: physical siemens. COMPONENT_MVAR: reactive power at unity voltage (Mvar for susceptance, MW for conductance). COMPONENT_BASE: per-unit on the component's own base (base_power MVA and voltage base) — a per-unit base, not a power at unity voltage, and not an alternative spelling of COMPONENT_MVAR; components whose per-unit data was historically on the system base record that system base in base_power. Fixed and switched shunts use ShuntAdmittanceUnitBasis instead, which omits COMPONENT_BASE because a shunt has no device MVA rating.",
      ),
    magnetizing_shunt: zod
      .object({
        real: zod.number().optional(),
        imag: zod.number().optional(),
      })
      .optional()
      .default({ real: 0 as const, imag: 0 as const })
      .describe("A complex number, given as its `real` and `imag` parts."),
    shunt_location: zod
      .enum(["PRIMARY", "STAR"])
      .optional()
      .default("PRIMARY")
      .describe(
        "Placement of a `ThreeWindingTransformer`'s magnetizing shunt admittance in the equivalent star model. PRIMARY: the full magnetizing shunt is applied on the winding-1 (primary) terminal side. STAR: the full magnetizing shunt is applied at the star node.",
      ),
  })
  .describe(
    "A three-winding transformer, modeled as an equivalent star: each referenced `TransformerCircuit` connects a terminal bus to the star (hidden) bus and carries that winding's series electrical data; availability is circuit-level. The pairwise measured impedances `r_12`/`x_12`, `r_23`/`x_23`, `r_31`/`x_31` (PSS/E CZ = 1, each in pu on the corresponding `base_power_12`/`base_power_23`/`base_power_31` and referenced to the first-index winding's base voltage) are optional and must be set together or all be absent; the star-leg impedances derived from them at parse time live on the circuits and are not synced back. Power-flow and Ybus assembly read the per-circuit star-leg impedances, not the pairwise fields. The model is described in Chapter 3.6 of J.D. Glover, M.S. Sarma and T. Overbye: Power Systems Analysis and Design.",
  );

export type ThreeWindingTransformer = zod.input<typeof ThreeWindingTransformer>;
export type ThreeWindingTransformerOutput = zod.output<
  typeof ThreeWindingTransformer
>;

