export type VSCACControlModesOutput = zod.output<typeof VSCACControlModes>;

export const VSCDCControlModes = zod
  .enum(["DC_POWER", "DC_VOLTAGE", "DC_VOLTAGE_DROOP"])
  .describe(
    "DC-side control mode of a voltage-source-converter (VSC) terminal. DC_POWER: converter controls active power transferred to the DC side. DC_VOLTAGE: converter controls the DC-side voltage. DC_VOLTAGE_DROOP: P-Vdc droop, V_dc = dc_setpoint - droop_gain * P_c.",
  );

export type VSCDCControlModes = zod.input<typeof VSCDCControlModes>;
export type VSCDCControlModesOutput = zod.output<typeof VSCDCControlModes>;

export const CombinedCycleConfiguration = zod
  .enum([
    "SingleShaftCombustionSteam",
    "SeparateShaftCombustionSteam",
    "DoubleCombustionOneSteam",
    "TripleCombustionOneSteam",
    "Other",
  ])
  .describe(
    "Shaft and turbine arrangement of a combined cycle plant: a single shaft carrying one combustion and one steam turbine, separate shafts for the two, two or three combustion turbines feeding one steam turbine, or `Other` for any arrangement outside these.",
  );

export type CombinedCycleConfiguration = zod.input<
  typeof CombinedCycleConfiguration
>;
export type CombinedCycleConfigurationOutput = zod.output<
  typeof CombinedCycleConfiguration
>;

export const FACTSControlDeviceControlMode = zod
  .enum(["OOS", "NML", "BYP"])
  .describe(
    "Operating mode of a FACTS control device. `OOS` (out-of-service): both series and shunt links are open. `NML` (normal): both series and shunt links are operating. `BYP` (bypass): the series link is bypassed (acts as a zero-impedance line) and the shunt link operates as a STATCOM (reactive-only).",
  );

export type FACTSControlDeviceControlMode = zod.input<
  typeof FACTSControlDeviceControlMode
>;
export type FACTSControlDeviceControlModeOutput = zod.output<
  typeof FACTSControlDeviceControlMode
>;

export const SwitchedAdmittanceControlMode = zod
  .enum([
    "UNDEFINED",
    "FIXED",
    "DISCRETE_VOLTAGE",
    "CONTINUOUS_VOLTAGE",
    "DISCRETE_REACTIVE_PLANT",
    "DISCRETE_REACTIVE_VSC",
    "DISCRETE_ADMITTANCE_REMOTE",
  ])
  .describe(
    "Control mode of a switched shunt admittance. `UNDEFINED` leaves the mode unspecified; `FIXED` holds the admittance at a constant value; `CONTINUOUS_VOLTAGE` adjusts it continuously to control voltage. The `DISCRETE_*` modes switch blocks in discrete steps to control voltage, a plant's reactive power, a voltage-source-converter terminal's reactive power, or a remote bus's admittance, respectively.",
  );

export type SwitchedAdmittanceControlMode = zod.input<
  typeof SwitchedAdmittanceControlMode
>;
export type SwitchedAdmittanceControlModeOutput = zod.output<
  typeof SwitchedAdmittanceControlMode
>;

export const ReserveDirection = zod
  .enum(["UP", "DOWN", "SYMMETRIC"])
  .describe(
    "Direction a reserve product is procured in. `UP` increases generation or reduces load when demand exceeds its expected level; `DOWN` decreases generation or increases load when demand falls below it; `SYMMETRIC` procures the same quantity in both directions. Upstream this distinction is a type parameter on the reserve; here it is flattened into a property.",
  );

export type ReserveDirection = zod.input<typeof ReserveDirection>;
export type ReserveDirectionOutput = zod.output<typeof ReserveDirection>;

export const TransformerControlObjective = zod
  .enum([
    "UNDEFINED",
    "VOLTAGE_DISABLED",
    "REACTIVE_POWER_FLOW_DISABLED",
    "ACTIVE_POWER_FLOW_DISABLED",
    "CONTROL_OF_DC_LINE_DISABLED",
    "ASYMMETRIC_ACTIVE_POWER_FLOW_DISABLED",
    "FIXED",
    "VOLTAGE",
    "REACTIVE_POWER_FLOW",
    "ACTIVE_POWER_FLOW",
    "CONTROL_OF_DC_LINE",
    "ASYMMETRIC_ACTIVE_POWER_FLOW",
  ])
  .describe(
    "Control objective of a transformer tap changer or phase shifter: a fixed tap position with no automatic adjustment (`FIXED`), or regulation of voltage magnitude at the controlled bus, reactive power flow, active power flow, asymmetric active power flow, or a DC line. Each regulating objective has a paired `_DISABLED` value naming the same control block while it is out of service, and `UNDEFINED` means no control objective is stated.",
  );

export type TransformerControlObjective = zod.input<
  typeof TransformerControlObjective
>;
export type TransformerControlObjectiveOutput = zod.output<
  typeof TransformerControlObjective
>;

export const TwoWindingTransformerShuntLocation = zod
  .enum(["PRIMARY", "SECONDARY", "SPLIT"])
  .describe(
    "Placement of a `TwoWindingTransformer`'s magnetizing shunt admittance on the two sides of its single circuit arc. PRIMARY: the full magnetizing shunt is applied on the primary (from) side. SECONDARY: the full magnetizing shunt is applied on the secondary (to) side. SPLIT: the full complex magnetizing shunt value is applied on BOTH sides.",
  );

export type TwoWindingTransformerShuntLocation = zod.input<
  typeof TwoWindingTransformerShuntLocation
>;
export type TwoWindingTransformerShuntLocationOutput = zod.output<
  typeof TwoWindingTransformerShuntLocation
>;

export const ThreeWindingTransformerShuntLocation = zod
  .enum(["PRIMARY", "STAR"])
  .describe(
    "Placement of a `ThreeWindingTransformer`'s magnetizing shunt admittance in the equivalent star model. PRIMARY: the full magnetizing shunt is applied on the winding-1 (primary) terminal side. STAR: the full magnetizing shunt is applied at the star node.",
  );

export type ThreeWindingTransformerShuntLocation = zod.input<
  typeof ThreeWindingTransformerShuntLocation
>;
export type ThreeWindingTransformerShuntLocationOutput = zod.output<
  typeof ThreeWindingTransformerShuntLocation
>;

export const VoltageUnitBasis = zod
  .enum(["NATURAL_UNITS", "COMPONENT_BASE"])
  .describe(
    "Unit basis a voltage setpoint is stored in. NATURAL_UNITS: kilovolts. COMPONENT_BASE: per-unit on the component's own base voltage (the connected bus's base voltage for AC setpoints — PSS/E RAW native for FACTS VSET — and the device voltage base PSS/E supplies for DC-line converters and CZ=2 transformer windings). There is no separate system-base option: bus-base per-unit is the device base for voltage.",
  );

export type VoltageUnitBasis = zod.input<typeof VoltageUnitBasis>;
export type VoltageUnitBasisOutput = zod.output<typeof VoltageUnitBasis>;

export const LoadConformity = zod
  .enum(["NON_CONFORMING", "CONFORMING", "UNDEFINED"])
  .describe(
    "WECC classification of how a load tracks voltage and frequency variation, used in dynamic studies to decide how it is modeled during a disturbance. `CONFORMING` responds predictably and follows standard load modeling practice; `NON_CONFORMING` does not, as with a constant power load or one behind a complex control system; `UNDEFINED` leaves the classification unstated.",
  );

export type LoadConformity = zod.input<typeof LoadConformity>;
export type LoadConformityOutput = zod.output<typeof LoadConformity>;

export const OperationalStates = zod
  .enum(["OFFLINE", "ONLINE", "STARTUP", "SHUTDOWN"])
  .describe(
    "The running on/off lifecycle of an in-service committable unit, mutually exclusive. OFFLINE: shut down and not synchronized. ONLINE: synchronized and able to produce. STARTUP: in its start-up sequence. SHUTDOWN: in its shut-down sequence. Availability is not one of these values: a unit on outage is `available = false`; an OFFLINE unit with `available = true` is in service and eligible for re-commitment and off-line ancillary services.",
  );

export type OperationalStates = zod.input<typeof OperationalStates>;
export type OperationalStatesOutput = zod.output<typeof OperationalStates>;

export const CommitmentModes = zod
  .enum([
    "UNCOMMITTED",
    "COMMITTED",
    "SELF_SCHEDULED",
    "RELIABILITY",
    "MUST_RUN",
  ])
  .describe(
    "Why a committable unit is (or would be) committed, orthogonal to its operational state. UNCOMMITTED: not committed, offline but available. COMMITTED: committed by the scheduling process (a planning model's commitment decision or a cleared schedule). SELF_SCHEDULED: scheduled by its owner rather than by the scheduling process. RELIABILITY: committed by the system operator for reliability rather than by the scheduling process. MUST_RUN: required to run by contract or operating constraint.",
  );

export type CommitmentModes = zod.input<typeof CommitmentModes>;
export type CommitmentModesOutput = zod.output<typeof CommitmentModes>;

export const BilateralProduct = zod
  .enum(["ENERGY", "CAPACITY", "ANCILLARY_SERVICE", "LOAD_OBLIGATION"])
  .describe(
    "Traded product of a bilateral transaction. ENERGY: energy. CAPACITY: capacity. ANCILLARY_SERVICE: an ancillary service. LOAD_OBLIGATION: a load obligation transfer.",
  );

export type BilateralProduct = zod.input<typeof BilateralProduct>;
export type BilateralProductOutput = zod.output<typeof BilateralProduct>;

export const MarketStage = zod
  .enum(["DAY_AHEAD", "REAL_TIME"])
  .describe(
    "Market stage a bilateral transaction was reported against. DAY_AHEAD: day-ahead. REAL_TIME: real-time.",
  );

export type MarketStage = zod.input<typeof MarketStage>;
export type MarketStageOutput = zod.output<typeof MarketStage>;

export const BilateralConfirmation = zod
  .enum([
    "DUAL_CONFIRM",
    "UNILATERAL_BUYER",
    "UNILATERAL_SELLER",
    "FIRST_REPORTER_DEEMED",
    "EXACT_MATCH_OR_REJECT",
  ])
  .describe(
    "Confirmation status a bilateral transaction settled under. DUAL_CONFIRM: both counterparties confirmed. UNILATERAL_BUYER: only the buyer confirmed. UNILATERAL_SELLER: only the seller confirmed. FIRST_REPORTER_DEEMED: the first-reported side is deemed confirmed. EXACT_MATCH_OR_REJECT: accepted only on an exact match between counterparties, otherwise rejected.",
  );

export type BilateralConfirmation = zod.input<typeof BilateralConfirmation>;
export type BilateralConfirmationOutput = zod.output<
  typeof BilateralConfirmation
>;
